def p(text='', bold=False):
    x = doc.add_paragraph(text)
    if bold:
        x.runs[0].bold = True
    return x
def h(text, level=1):
    return doc.add_heading(text, level)
def table(headers, rows, widths=None):
    t = doc.add_table(rows=1, cols=len(headers))
    t.autofit = False
    for c, text in zip(t.rows[0].cells,headers): c.text = text
    for row in rows:
        for c, text in zip(t.add_row().cells,row): c.text = text
    for ri,r in enumerate(t.rows):
        for ci,c in enumerate(r.cells):
            if widths: c.width = Cm(widths[ci])
            pr=c._tc.get_or_add_tcPr()
            borders=OxmlElement('w:tcBorders')
            for edge in ['top','left','bottom','right']:
                e=OxmlElement('w:'+edge); e.set(qn('w:val'),'single'); e.set(qn('w:sz'),'4'); e.set(qn('w:color'),'D9D9D9'); borders.append(e)
            pr.append(borders)
            margins=OxmlElement('w:tcMar')
            for side in ['top','left','bottom','right']:
                e=OxmlElement('w:'+side); e.set(qn('w:w'),'85'); e.set(qn('w:type'),'dxa'); margins.append(e)
            pr.append(margins)
            if ri==0:
                sh=OxmlElement('w:shd'); sh.set(qn('w:fill'),'E7E6E6'); pr.append(sh)
            for par in c.paragraphs:
                par.paragraph_format.first_line_indent=Cm(0)
                par.paragraph_format.line_spacing=1.05
                par.paragraph_format.space_after=Pt(4)
                par.alignment=WD_ALIGN_PARAGRAPH.LEFT
                for run in par.runs:
                    run.font.size=Pt(11)
                    run.bold=ri==0
        if ri==0:
            repeat=OxmlElement('w:tblHeader'); r._tr.get_or_add_trPr().append(repeat)
    p()
    return t

